export function createLedger({ expectedAmounts = {} } = {}) {
  const handledIds = new Set();
  const transactions = {};
  const deferredRefunds = {};

  function handle(event) {
    if (!event || !["charge.success", "charge.failed", "charge.abandoned", "refund.processed"].includes(event.type)) {
      return { applied: false, reason: "unknown-type", status: null };
    }

    if (handledIds.has(event.id)) {
      const status = transactions[event.reference]?.status || null;
      return { applied: false, reason: "duplicate", status };
    }

    if ((event.type === "charge.success" || event.type === "refund.processed") && (!Number.isInteger(event.amountKobo) || event.amountKobo <= 0)) {
      const status = transactions[event.reference]?.status || null;
      return { applied: false, reason: "invalid-amount", status };
    }

    handledIds.add(event.id);

    if (!transactions[event.reference]) {
      transactions[event.reference] = {
        reference: event.reference,
        status: "pending",
        amountKobo: expectedAmounts[event.reference] || null,
        refundedKobo: 0
      };
    }

    const transaction = transactions[event.reference];

    switch (event.type) {
      case "charge.success":
        if (["success", "partially_refunded", "refunded", "amount_mismatch"].includes(transaction.status)) {
          return { applied: false, reason: "terminal", status: transaction.status };
        }
        if (expectedAmounts[event.reference] !== undefined && expectedAmounts[event.reference] !== event.amountKobo) {
          transaction.status = "amount_mismatch";
          return { applied: true, reason: "amount-mismatch", status: transaction.status };
        }
        transaction.status = "success";
        transaction.amountKobo = transaction.amountKobo || event.amountKobo;
        applyDeferredRefunds(transaction);
        return { applied: true, reason: null, status: transaction.status };

      case "charge.failed":
        if (transaction.status === "pending" || transaction.status === "abandoned") {
          transaction.status = "failed";
          return { applied: true, reason: null, status: transaction.status };
        }
        return { applied: false, reason: "stale", status: transaction.status };

      case "charge.abandoned":
        if (transaction.status === "pending") {
          transaction.status = "abandoned";
          return { applied: true, reason: null, status: transaction.status };
        }
        return { applied: false, reason: "stale", status: transaction.status };

      case "refund.processed":
        if (transaction.status === "success" || transaction.status === "partially_refunded") {
          const newRefundedKobo = transaction.refundedKobo + event.amountKobo;
          if (newRefundedKobo > transaction.amountKobo) {
            return { applied: false, reason: "over-refund", status: transaction.status };
          }
          transaction.refundedKobo = newRefundedKobo;
          transaction.status = newRefundedKobo === transaction.amountKobo ? "refunded" : "partially_refunded";
          return { applied: true, reason: null, status: transaction.status };
        }
        if (transaction.status === "refunded") {
          return { applied: false, reason: "over-refund", status: transaction.status };
        }
        if (transaction.status === "pending" || transaction.status === "abandoned" || transaction.status === "failed") {
          if (!deferredRefunds[event.reference]) {
            deferredRefunds[event.reference] = [];
          }
          deferredRefunds[event.reference].push(event);
          return { applied: false, reason: "deferred", status: transaction.status };
        }
        return { applied: false, reason: "terminal", status: transaction.status };
    }
  }

  function applyDeferredRefunds(transaction) {
    const refunds = deferredRefunds[transaction.reference] || [];
    for (const refundEvent of refunds) {
      const newRefundedKobo = transaction.refundedKobo + refundEvent.amountKobo;
      if (newRefundedKobo <= transaction.amountKobo) {
        transaction.refundedKobo = newRefundedKobo;
        transaction.status = newRefundedKobo === transaction.amountKobo ? "refunded" : "partially_refunded";
      }
    }
    delete deferredRefunds[transaction.reference];
  }

  function get(reference) {
    return transactions[reference];
  }

  return { handle, get };
}
